declare(strict_types=1);
require_once __DIR__.'/TestDatabase.php';
use PHPUnit\Framework\TestCase;
use Sexogate\{SourceApi,SourceCatalog,Principal,RuleViolation,Commerce,Worker};
final class SourceApiTest extends TestCase
{
    private function store(?callable $fetch=null):array
    {self::assertTrue(class_exists(SourceApi::class),'Persistent supplier API connection is missing.');$f=new TestDatabase();return [$f,new SourceApi($f->db,$f->config,$fetch),new Principal('api-test-admin','admin',true)];}
    private function response(string $resource,int $page):array
    {$category=$resource==='categories';return ['status'=>200,'total'=>1,'body'=>json_encode([['id'=>$category?5:21,'name'=>$category?'İç Giyim':'Ölçü ve Özellikler','permalink'=>'https://www.xshopum.com/'.($category?'ic-giyim/':'gercek-urun/'),'sku'=>'XS-21','prices'=>['price'=>'14950','currency_code'=>'TRY','currency_minor_unit'=>2],'is_in_stock'=>true,'images'=>[],'categories'=>[]]],JSON_UNESCAPED_UNICODE)];}
    public function testPagesProduceOneCompletePrivateSnapshotWithoutWarehouseWrites():void
    {[$f,$s,$a]=$this->store(fn($resource,$page)=>$this->response($resource,$page));$run=$s->start('xshopum',bin2hex(random_bytes(16)),$a);self::assertSame($run['id'],$s->start('xshopum',bin2hex(random_bytes(16)),$a)['id']);self::assertCount(0,(new SourceCatalog($f->db,$f->config))->listing($a));$s->process($run['id'],'categories',1,1);$s->process($run['id'],'categories',1,1);$s->process($run['id'],'products',1,1);$latest=(new SourceCatalog($f->db,$f->config))->listing($a);self::assertCount(1,$latest);self::assertSame(1,(int)$latest[0]['product_count']);self::assertSame(1,(int)$latest[0]['category_count']);self::assertSame('complete',$s->run($run['id'],$a)['status']);self::assertSame(2,(int)$f->db->one('SELECT COUNT(*) n FROM source_api_pages')['n']);self::assertSame(0,(int)$f->db->one('SELECT COUNT(*) n FROM inventory_balance')['n']);self::assertSame(0,(int)$f->db->one('SELECT COUNT(*) n FROM products')['n']);$payload=json_decode($f->db->one("SELECT payload FROM source_catalog_records WHERE kind='product'")['payload'],true);self::assertSame(14950,$payload['quotedRetailMinor']);self::assertNull($payload['supplierQuantity']);self::assertSame('Ölçü ve Özellikler',$payload['title']);}
    public function testAccessDenialOpensCircuitAndCannotEnableAutomation():void
    {[$f,$s,$a]=$this->store(fn()=>['status'=>403,'total'=>null,'body'=>'<html>Access denied</html>']);$r=$s->start('xshopum',bin2hex(random_bytes(16)),$a);$s->process($r['id'],'categories',1,1);self::assertSame('access_required',$s->run($r['id'],$a)['status']);$row=$f->db->one("SELECT enabled,last_error FROM source_api_connections WHERE vendor='xshopum'");self::assertSame(0,(int)$row['enabled']);self::assertSame('SOURCE_API_HTTP_403',$row['last_error']);self::assertSame([], (new SourceCatalog($f->db,$f->config))->listing($a));$this->expectException(RuleViolation::class);$s->configure('xshopum',true,60,$a);}
    public function testMissingPageAndDriftingTotalsNeverReplaceLastGoodBatch():void
    {[$f,$s,$a]=$this->store(fn($resource,$page)=>$this->response($resource,$page));$r=$s->start('xshopum',bin2hex(random_bytes(16)),$a);$s->process($r['id'],'categories',1,1);$s->process($r['id'],'products',1,1);$batch=(new SourceCatalog($f->db,$f->config))->listing($a)[0]['id'];$f->db->execute("UPDATE source_api_connections SET last_attempt_at=NULL WHERE vendor='xshopum'");$bad=new SourceApi($f->db,$f->config,function($resource,$page){$r=$this->response($resource,$page);if($resource==='products')$r['total']=2;return $r;});$new=$bad->start('xshopum',bin2hex(random_bytes(16)),$a);$bad->process($new['id'],'categories',1,1);try{$bad->process($new['id'],'products',1,3);self::fail('Partial catalog was accepted');}catch(RuleViolation $e){self::assertSame('SOURCE_API_COUNT_MISMATCH',$e->rule);}self::assertSame('failed',$bad->run($new['id'],$a)['status']);self::assertSame($batch,(new SourceCatalog($f->db,$f->config))->listing($a)[0]['id']);}
    public function testTimeoutIsRetriedAndMissingSupplierCredentialsStayBlocked():void
    {[$f,$s,$a]=$this->store(fn()=>throw new RuleViolation('SOURCE_API_TIMEOUT','Timeout',503));$r=$s->start('xshopum',bin2hex(random_bytes(16)),$a);try{$s->process($r['id'],'categories',1,1);self::fail('Timeout hidden');}catch(RuleViolation $e){self::assertSame('SOURCE_API_TIMEOUT',$e->rule);}self::assertSame('running',$s->run($r['id'],$a)['status']);try{$s->process($r['id'],'categories',1,3);}catch(RuleViolation){}self::assertSame('failed',$s->run($r['id'],$a)['status']);foreach(['liona','sistina'] as $vendor){try{$s->start($vendor,bin2hex(random_bytes(16)),$a);self::fail('Undocumented API accepted');}catch(RuleViolation $e){self::assertSame('SOURCE_API_CREDENTIALS_REQUIRED',$e->rule);}}$this->expectException(RuleViolation::class);$s->listing(new Principal('warehouse','warehouse',true));}
    public function testIncompleteSnapshotCannotBeOpenedAndStalledTimerIsRecovered():void
    {[$f,$s,$a]=$this->store(fn($resource,$page)=>$this->response($resource,$page));$r=$s->start('xshopum',bin2hex(random_bytes(16)),$a);$s->process($r['id'],'categories',1,1);try{(new SourceCatalog($f->db,$f->config))->records($r['batchId'],[],$a);self::fail('Incomplete snapshot was exposed as normal catalog');}catch(RuleViolation $e){self::assertSame(404,$e->status);}$s->process($r['id'],'products',1,1);$s->configure('xshopum',true,60,$a);$f->db->execute("UPDATE source_api_connections SET next_run_at=DATE_SUB(CURRENT_TIMESTAMP(3),INTERVAL 1 MINUTE) WHERE vendor='xshopum'");self::assertSame(1,$s->scheduleDue());self::assertSame(0,$s->scheduleDue());$run=$f->db->one("SELECT active_run_id FROM source_api_connections WHERE vendor='xshopum'")['active_run_id'];$f->db->execute('UPDATE source_api_runs SET started_at=DATE_SUB(CURRENT_TIMESTAMP(3),INTERVAL 2 HOUR) WHERE id=?',[$run]);$s->scheduleDue();self::assertSame('failed',$s->run($run,$a)['status']);self::assertNull($f->db->one("SELECT active_run_id FROM source_api_connections WHERE vendor='xshopum'")['active_run_id']);}
    public function testTransportAllowsOnlyFixedEndpointsAndPublicNetworkAddresses():void
    {foreach(['127.0.0.1','10.0.0.1','100.64.0.1','169.254.169.254','192.168.1.1','198.18.0.1','::1','::ffff:8.8.8.8','fc00::1','fe80::1','ff02::1'] as $ip)self::assertFalse(Sexogate\SupplierApiHttp::publicIp($ip),$ip);self::assertTrue(Sexogate\SupplierApiHttp::publicIp('8.8.8.8'));$url=Sexogate\SupplierApiHttp::endpoint('products',2);self::assertStringContainsString('stock_status=instock%2Coutofstock%2Conbackorder',$url);self::assertStringStartsWith('https://www.xshopum.com/wp-json/wc/store/v1/',$url);self::assertStringNotContainsString('orderby=id',Sexogate\SupplierApiHttp::endpoint('categories',1));$this->expectException(RuleViolation::class);Sexogate\SupplierApiHttp::endpoint('https://127.0.0.1/',1);}
    public function testHttpConnectionRequiresIdentityRoleMfaAndCsrf():void
    {
        $f=new TestDatabase();$session=new Symfony\Component\HttpFoundation\Session\Session(new Symfony\Component\HttpFoundation\Session\Storage\MockArraySessionStorage());$kernel=new Sexogate\Kernel($f->db,$f->config,$session);$url='http://127.0.0.1:3183/test/api/admin/source-api';$get=fn()=>Symfony\Component\HttpFoundation\Request::create($url);self::assertSame(401,$kernel->handle($get())->getStatusCode());
        $f->db->execute("INSERT INTO `user`(id,name,email,emailVerified,role,twoFactorEnabled) VALUES('api-http','Katalog','api-http@example.invalid',true,'warehouse',true)");foreach(['user_id'=>'api-http','epoch'=>0,'mfa'=>true,'auth_at'=>time(),'last_seen'=>time()] as $key=>$value)$session->set($key,$value);self::assertSame(403,$kernel->handle($get())->getStatusCode());$f->db->execute("UPDATE `user` SET role='catalog' WHERE id='api-http'");self::assertSame(200,$kernel->handle($get())->getStatusCode());
        $post=fn($csrf)=>Symfony\Component\HttpFoundation\Request::create($url,'POST',[],[],[],['CONTENT_TYPE'=>'application/json','HTTP_ORIGIN'=>'http://127.0.0.1:3183','HTTP_X_CSRF_TOKEN'=>$csrf],json_encode(['action'=>'start','vendor'=>'xshopum','key'=>'http-api-test-start']));self::assertSame(403,$kernel->handle($post('bad'))->getStatusCode());$csrf=json_decode($kernel->handle(Symfony\Component\HttpFoundation\Request::create('http://127.0.0.1:3183/test/api/session'))->getContent(),true)['csrfToken'];$session->set('mfa',false);self::assertSame(403,$kernel->handle($post($csrf))->getStatusCode());$session->set('mfa',true);self::assertSame(200,$kernel->handle($post($csrf))->getStatusCode());self::assertSame(1,(int)$f->db->one('SELECT COUNT(*) n FROM source_api_runs')['n']);self::assertSame(1,(int)$f->db->one("SELECT COUNT(*) n FROM jobs WHERE type='source.api.page'")['n']);$page=$kernel->handle(Symfony\Component\HttpFoundation\Request::create('http://127.0.0.1:3183/test/yonetim/tedarikci-katalogu'));self::assertSame(200,$page->getStatusCode());self::assertStringContainsString('Canlı API bağlantıları',$page->getContent());self::assertStringContainsString('no-store',$page->headers->get('Cache-Control'));
    }
}
